func eventKindIntent(kind string) string {
	switch kind {
	case "section":
		return "primary"
	case "cli":
		return "warning"
	case "log":
		return "info"
	case "error":
		return "fail"
	case "pw_action":
		return "info"
	case "pw_assert":
		return "pass"
	case "pw_step":
		return "info"
	case "assertion":
		return "pass"
	case "http_call":
		return "accent"
	case "artifact":
		return "secondary"
	case "failure":
		return "fail"
	case "skip":
		return "skip"
	case "metric":
		return "pass"
	case "gantt":
		return "info"
	case "state_change":
		return "info"
	case "token_usage":
		return "info"
	default:
		return "info"
	}
}

func truncateMessage(msg string, maxLen int) string {
	msg = stripANSI(msg)
	if len(msg) <= maxLen {
		return msg
	}
	return msg[:maxLen] + "..."
}

